// Turns the queued sheet row into a standard content request.
const cfg = $('Agent Config').first().json;
const row = $('Pick Next Topic').first().json;

const ALIASES = { li: 'linkedin', linkedin: 'linkedin', ig: 'instagram', insta: 'instagram', instagram: 'instagram',
  fb: 'facebook', facebook: 'facebook', yt: 'youtube', youtube: 'youtube', shorts: 'youtube' };
const parsePlatforms = (s) => [...new Set(String(s || '').toLowerCase().split(/[\s,;|]+/).map(p => ALIASES[p]).filter(Boolean))];

const videoRef = String(row.Video || '').trim();
const m = videoRef.match(/(?:\/d\/|[?&]id=)([\w-]{20,})/);
const driveFileId = m ? m[1] : (/^[\w-]{20,}$/.test(videoRef) ? videoRef : '');

let platforms = parsePlatforms(row.Platforms);
if (!platforms.length) platforms = parsePlatforms(cfg.defaultPlatforms);

return [{ json: {
  source: 'sheet',
  topic: String(row.Topic || '').trim(),
  notes: String(row.Notes || '').trim(),
  platforms,
  videoSource: driveFileId ? 'drive' : 'ai',
  driveFileId,
  telegramFileId: '',
  rowNumber: row.row_number,
} }];

// Understands messages like:
//   "Reel about my 3 biggest pricing mistakes"
//   (video attached, caption = topic)
//   "https://drive.google.com/file/d/<id>/view  launch recap\nto: linkedin, youtube"
const cfg = $('Agent Config').first().json;
const msg = $json.message || {};
let text = String(msg.text || msg.caption || '').trim();

const ALIASES = { li: 'linkedin', linkedin: 'linkedin', ig: 'instagram', insta: 'instagram', instagram: 'instagram',
  fb: 'facebook', facebook: 'facebook', yt: 'youtube', youtube: 'youtube', shorts: 'youtube' };
const parsePlatforms = (s) => [...new Set(String(s || '').toLowerCase().split(/[\s,;|]+/).map(p => ALIASES[p]).filter(Boolean))];

let platforms = [];
text = text.replace(/^\s*(?:to|platforms?)\s*:\s*(.+)$/im, (_, list) => { platforms = parsePlatforms(list); return ''; });
if (!platforms.length) platforms = parsePlatforms(cfg.defaultPlatforms);

let driveFileId = '';
text = text.replace(/https?:\/\/drive\.google\.com\/\S*?(?:\/d\/|[?&]id=)([\w-]{20,})\S*/i, (_, id) => { driveFileId = id; return ''; });

const doc = msg.document && /^video\//.test(msg.document.mime_type || '') ? msg.document : null;
const tgVideo = msg.video || doc;
const topic = text.replace(/\s+\n/g, '\n').trim();

const videoSource = tgVideo ? 'telegram' : driveFileId ? 'drive' : 'ai';
const tooBig = tgVideo && tgVideo.file_size > 20 * 1024 * 1024;
const valid = !tooBig && !(videoSource === 'ai' && topic.length < 5) && !/^\/(start|help)\b/.test(topic);

return [{ json: {
  valid,
  invalidReason: tooBig ? 'too_big' : 'no_topic',
  source: 'telegram',
  topic,
  notes: '',
  platforms,
  videoSource,
  driveFileId,
  telegramFileId: tgVideo ? tgVideo.file_id : '',
  rowNumber: null,
} }];

