// Combines the request with the AI output and formats every platform's text.
const req = $('Content Request').first().json;
const ai = $json.output;

const clean = (s) => String(s || '').trim();
const hashtags = (ai.hashtags || []).map(h => '#' + String(h).replace(/^#/, '').replace(/[^\p{L}\p{N}_]/gu, '')).filter(h => h.length > 1);
const tagLine = hashtags.join(' ');

// LinkedIn "little text" format: reserved characters must be escaped or the post gets cut off.
const liEscape = (s) => s.replace(/[\\|{}@\[\]()<>#*_~]/g, ch => '\\' + ch);
// YouTube rejects < and > in titles and descriptions.
const ytSafe = (s) => s.replace(/[<>]/g, '');

let ytTitle = ytSafe(clean(ai.youtube_title)).replace(/#shorts/ig, '').trim();
ytTitle = (ytTitle.length > 91 ? ytTitle.slice(0, 90).trim() + '…' : ytTitle) + ' #Shorts';

const pkg = {
  ...req,
  hook: clean(ai.hook),
  videoScript: clean(ai.video_script),
  hashtags,
  linkedinCommentary: liEscape(`${clean(ai.linkedin_post)}\n\n${tagLine}`.trim()),
  instagramCaption: `${clean(ai.instagram_caption)}\n\n${tagLine}`.trim().slice(0, 2200),
  facebookText: `${clean(ai.facebook_post)}\n\n${tagLine}`.trim(),
  youtubeTitle: ytTitle,
  youtubeDescription: ytSafe(`${clean(ai.youtube_description)}\n\n${tagLine} #Shorts`).slice(0, 4900),
  youtubeTags: hashtags.map(h => h.slice(1)).join(','),
};

const cut = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const names = { linkedin: 'LinkedIn', instagram: 'Instagram', facebook: 'Facebook', youtube: 'YouTube Shorts' };
const sections = [];
if (req.platforms.includes('linkedin')) sections.push(`— LinkedIn —\n${cut(`${clean(ai.linkedin_post)}\n\n${tagLine}`, 900)}`);
if (req.platforms.includes('instagram')) sections.push(`— Instagram —\n${cut(pkg.instagramCaption, 700)}`);
if (req.platforms.includes('facebook')) sections.push(`— Facebook —\n${cut(pkg.facebookText, 500)}`);
if (req.platforms.includes('youtube')) sections.push(`— YouTube —\n${pkg.youtubeTitle}\n${cut(pkg.youtubeDescription, 300)}`);

const videoLabel = { ai: 'AI avatar video (HeyGen)', telegram: 'your Telegram video', drive: 'your Google Drive video' }[req.videoSource];
pkg.previewText = cut([
  `🎬 Draft ready for approval`,
  `Topic: ${req.topic || '(from your video)'}`,
  `Video: ${videoLabel}`,
  `Posting to: ${req.platforms.map(p => names[p]).join(', ')}`,
  '',
  sections.join('\n\n'),
].join('\n'), 3900);

return [{ json: pkg }];

