// All three video sources end here with the video in binary property "data".
const item = $input.first();
if (!item.binary || !item.binary.data) throw new Error('No video file was received from the video source step.');
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const bin = item.binary.data;
if (!String(bin.mimeType || '').startsWith('video/')) bin.mimeType = 'video/mp4';
if (!bin.fileName || !/\.\w+$/.test(bin.fileName)) bin.fileName = 'social-video.mp4';
return [{ json: { videoBytes: buf.length, fileName: bin.fileName }, binary: { data: bin } }];

// The approval step only returns the button click, so bring back the package and the video file.
const pkg = $('Build Post Package').first().json;
const video = $('Video Ready').first();
return [{ json: { ...pkg, videoBytes: video.json.videoBytes, fileName: video.json.fileName }, binary: video.binary }];

