// LinkedIn wants the file in the byte ranges it returned (4 MB parts).
const item = $input.first();
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const { uploadInstructions, video, uploadToken } = item.json.value;
const out = [];
for (let i = 0; i < uploadInstructions.length; i++) {
  const { uploadUrl, firstByte, lastByte } = uploadInstructions[i];
  const chunk = await this.helpers.prepareBinaryData(Buffer.from(buf.subarray(firstByte, lastByte + 1)), `part-${i}.bin`, 'application/octet-stream');
  out.push({ json: { partIndex: i, uploadUrl, video, uploadToken: uploadToken || '' }, binary: { chunk } });
}
return out;

const parts = $input.all();
const first = $('LinkedIn: Split Into Parts').first().json;
return [{ json: {
  video: first.video,
  uploadToken: first.uploadToken,
  uploadedPartIds: parts.map(p => p.json.headers.etag),
} }];

